import { CHECK_ELEMENT_ATTR } from "../services/pluncAttribute";
export function composeCheckDirectiveProcessor(appCtx) {
    return function processCheckDirective(elementCtx, dataCtx) {
        const elementsToProcess = appCtx.__querySelectAllByPluncAttribute(elementCtx, CHECK_ELEMENT_ATTR);
        elementsToProcess.forEach((element) => {
            if (appCtx.__isElementLocked(element)) {
                return;
            }
            const checkExpression = appCtx.__pluncAttributeValueGetter(element, CHECK_ELEMENT_ATTR);
            if (checkExpression === null || checkExpression.trim() === "") {
                return;
            }
            const evaluatedResult = appCtx.__resolveExpression(dataCtx, checkExpression);
            if (typeof evaluatedResult === "boolean") {
                evaluatedResult
                    ? element.setAttribute("checked", "true")
                    : element.removeAttribute("checked");
            }
            appCtx.__lockElement(element);
        });
    };
}
